const teachers=[{name:'林老師',subject:'科學',color:'#cadcf4',shirt:'#aea4d3',desc:'用有趣的例子，陪你探索生活中的科學。',topic:'植物的小秘密',intro:'你好！我是林老師。今天一起探索植物吧。你有種過植物嗎？',question:'植物要健康生長，需要甚麼？',options:['陽光和水','汽水和糖果','玩具和書本','只有泥土'],correct:0,explain:'植物需要適當的陽光和水。陽光幫助植物製造養分，水分讓植物維持生長。'},{name:'陳老師',subject:'數學',color:'#d9e2f5',shirt:'#889cbf',desc:'一步一步想清楚，讓數學變得容易理解。',topic:'一起分享蘋果',intro:'你好！我是陳老師。我們來分享蘋果吧。你平常喜歡吃甚麼水果？',question:'6 個蘋果平均分給 3 個人，每人有幾個？',options:['1 個','2 個','3 個','6 個'],correct:1,explain:'答對的方法是 6 除以 3，等於 2，所以每人得到 2 個蘋果。'},{name:'May 老師',subject:'英語',color:'#e2def4',shirt:'#b2a3cc',desc:'從日常小對話開始，自信地說出英語。',topic:'用英語打招呼',intro:'Hello！我是 May 老師。今天一起練習打招呼吧。你想怎樣介紹自己？',question:'早上見到老師，應該怎樣打招呼？',options:['Good night!','Goodbye!','Good morning!','Thank you!'],correct:2,explain:'Good morning 是早安，適合早上見面時使用。試試跟著說：Good morning!'}];
let selected=0,page=1,stage=0,answered=false,last='',recognition=null,listening=false,epoch=0;
const app=document.querySelector('#app');
function portrait(i){let t=teachers[i];return `<svg class="portrait" viewBox="0 0 200 200" aria-hidden="true"><circle cx="100" cy="100" r="98" fill="${t.color}"/><path d="M50 104Q35 24 100 23Q169 20 153 125L49 130Z" fill="#594e50"/><path d="M27 199Q29 139 77 137L123 137Q174 139 175 199" fill="${t.shirt}"/><path d="M82 126v20l18 20 19-20v-25" fill="#edbc9f"/><ellipse cx="100" cy="88" rx="44" ry="54" fill="#f7ceb2"/><path d="M55 78Q57 29 100 31Q145 28 147 77Q120 64 107 45Q88 70 55 78" fill="#594e50"/><path d="M78 143l22 23-14 16-19-34M121 143l-21 23 14 16 20-34" fill="#fafafe"/><circle cx="84" cy="91" r="3" fill="#49424b"/><circle cx="117" cy="91" r="3" fill="#49424b"/><path d="M88 113q13 13 25-1" fill="none" stroke="#b46d66" stroke-width="3" stroke-linecap="round"/>${i===1?'<g fill="none" stroke="#535369" stroke-width="3"><rect x="66" y="80" width="30" height="23" rx="7"/><rect x="105" y="80" width="30" height="23" rx="7"/><path d="M96 88h9"/></g>':''}</svg>`}
function stop(){epoch++;window.speechSynthesis?.cancel();recognition?.abort();recognition=null;listening=false}
function speak(text){last=text;window.speechSynthesis?.cancel();if(!('speechSynthesis'in window)){notice('這個瀏覽器未支援朗讀，可閱讀畫面字幕。');return}let id=epoch;const u=new SpeechSynthesisUtterance(text);u.lang='zh-HK';u.rate=.88;u.onstart=()=>{if(id===epoch){document.querySelector('.presence')?.classList.add('speaking');notice('老師正在說話…')}};u.onend=()=>{if(id===epoch){document.querySelector('.presence')?.classList.remove('speaking');notice('輪到你了，可以說話或輸入文字。')}};u.onerror=()=>{if(id===epoch){document.querySelector('.presence')?.classList.remove('speaking');notice('朗讀未能播放，可按「重聽」再試，或閱讀字幕。')}};speechSynthesis.speak(u)}
function notice(s){let n=document.querySelector('#notice');if(n)n.textContent=s}
function render(){document.querySelector('#step1').classList.toggle('active',page===1);document.querySelector('#step2').classList.toggle('active',page===2);if(page===1){app.innerHTML=`<section class="intro"><h1>今天，想跟誰一起學習？</h1><p>選一位老師，從一段輕鬆的對話開始。</p></section><div class="cards">${teachers.map((t,i)=>`<button class="teacher ${selected===i?'selected':''}" aria-pressed="${selected===i}" data-select="${i}"><span class="check">✓</span>${portrait(i)}<h2>${t.name}</h2><span class="badge">${t.subject}</span><p>${t.desc}</p><span class="subtle">今日話題：${t.topic}</span></button>`).join('')}</div><div class="start"><button class="primary" id="start">和${teachers[selected].name}開始對話　 →</button><p>可以用語音，也可以用文字慢慢回答。</p></div>`;document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=+b.dataset.select;render();document.querySelector(`[data-select="${selected}"]`).focus()});document.querySelector('#start').onclick=()=>{stop();page=2;stage=0;render();speak(teachers[selected].intro)};return}let t=teachers[selected];app.innerHTML=`<div class="session-head"><button class="quiet" id="back">← 更換老師</button><h1>${t.topic}<small>與 ${t.name} 一起探索</small></h1><span class="badge">${t.subject}</span></div><section class="studio"><aside class="presence">${portrait(selected)}<div><h2>${t.name}</h2><p>不急，我們一起想想。</p><div class="wave">${'<i></i>'.repeat(23)}</div></div></aside><div class="lesson"><div class="lesson-label"><span>今天的小對話</span><span id="progress">暖身時間</span></div><div id="content" aria-live="polite"></div><form class="reply" id="form"><input id="text" aria-label="你的回答" placeholder="輸入你想說的話…" maxlength="300"><button class="secondary">送出</button></form></div></section><div class="toolbar"><button class="primary" id="mic">♩ 開始說話</button><button class="secondary" id="replay">↻ 重聽</button><button class="quiet" id="end">結束對話</button></div><p class="notice" id="notice" role="status">按「開始說話」開啟麥克風，或直接輸入文字。</p>`;document.querySelector('#back').onclick=home;document.querySelector('#end').onclick=()=>{stop();stage=3;content()};document.querySelector('#replay').onclick=()=>speak(last);document.querySelector('#mic').onclick=listen;document.querySelector('#form').onsubmit=e=>{e.preventDefault();submitText()};content()}
function home(){stop();page=1;render()}
function content(){let t=teachers[selected],c=document.querySelector('#content');document.querySelector('#form').hidden=stage===3;document.querySelector('#mic').disabled=stage===3;document.querySelector('#progress').textContent=['暖身時間','一起想想','一起想想','已完成'][stage];if(stage===0){last=t.intro;c.innerHTML=`<div class="bubble">${t.intro}</div><p class="feedback">先和老師打個招呼，再試試一道小問題。</p><button class="secondary" id="question">準備好了，開始小問題</button>`;document.querySelector('#question').onclick=question}else if(stage===1){last=t.question;c.innerHTML=`<div class="bubble">${t.question}</div><div class="answers">${t.options.map((o,i)=>`<button class="answer" data-answer="${i}"><b>${'ABCD'[i]}</b>${o}</button>`).join('')}</div><p class="feedback" id="feedback">點選答案，也可以說出 A、B、C 或 D。</p><div id="next"></div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer))}else if(stage===3){last='今天的練習完成了，謝謝你和我一起探索！';c.innerHTML='<div class="complete"><span class="badge">今天又學會了一點</span><h2>做得好，我們下次見！</h2><p>謝謝你願意開口，也願意動腦想想。</p><button class="primary" id="again">再練習一次</button><button class="quiet" id="choose">選擇其他老師</button></div>';document.querySelector('#again').onclick=()=>{stop();stage=0;render();speak(t.intro)};document.querySelector('#choose').onclick=home}}
function question(){stop();stage=1;answered=false;content();speak(teachers[selected].question)}
function answer(i){if(answered)return;answered=true;let t=teachers[selected];document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;b.classList.toggle('chosen',+b.dataset.answer===i)});let message=(i===t.correct?'答對了！':'一起看看：正確答案是 '+t.options[t.correct]+'。')+t.explain;document.querySelector('#feedback').textContent=message;document.querySelector('#next').innerHTML='<button class="secondary" id="finish">完成今天的練習 →</button>';document.querySelector('#finish').onclick=()=>{stop();stage=3;content();speak(last)};speak(message)}
function submitText(value){const input=document.querySelector('#text');let s=(value||input.value).trim();if(!s)return;input.value='';if(stage===0){question();let p=document.createElement('p');p.className='student';p.textContent='你：'+s;document.querySelector('#content').prepend(p);speak('謝謝你分享！'+teachers[selected].question)}else if(stage===1&&!answered){let t=teachers[selected];let i=t.options.findIndex(o=>s.includes(o));if(i<0&&/^[abcd]$/i.test(s))i='ABCD'.indexOf(s.toUpperCase());if(i>=0)answer(i);else notice('收到你的想法：「'+s+'」。請點選最接近的答案，或輸入 A、B、C、D。')}else notice('這題已完成，可以按「完成今天的練習」。')}
function listen(){if(listening){recognition?.stop();return}const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){notice('這個瀏覽器未支援語音辨識，請用下方文字輸入；建議以 Chrome 或 Edge 試用語音。');document.querySelector('#text').focus();return}window.speechSynthesis?.cancel();let id=epoch;const r=new R();recognition=r;r.lang='zh-HK';r.interimResults=false;r.onstart=()=>{listening=true;document.querySelector('#mic').textContent='■ 停止聆聽';notice('正在聆聽，請說話…')};r.onresult=e=>{if(id===epoch)submitText(e.results[0][0].transcript.replace(/[。.!！]/g,''))};r.onerror=e=>{if(id===epoch)notice(e.error==='not-allowed'?'未能使用麥克風。請允許瀏覽器使用麥克風，或改用文字輸入。':'未能辨識語音，請再試一次或輸入文字。')};r.onend=()=>{listening=false;if(id===epoch){document.querySelector('#mic').textContent='♩ 開始說話';if(document.querySelector('#notice').textContent.startsWith('正在聆聽'))notice('沒有收到語音，請再試一次或輸入文字。')}};try{r.start()}catch{notice('麥克風暫時未能啟動，請使用文字輸入。')}}
document.querySelector('.brand').onclick=e=>{e.preventDefault();home()};window.addEventListener('pagehide',stop);render();
